const $=s=>document.querySelector(s);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const store=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let settings={intro:true,bot:true,motion:true,...read('nm-shop-settings',{})},preferences=read('nm-shop-privacy',null),botTimer,observers=[];
export function disposeShelves(){observers.forEach(o=>o.disconnect());observers=[];}
export function mountHomeRows(){disposeShelves();document.querySelectorAll('.category-shelf').forEach(shelf=>{const track=shelf.querySelector('.shelf-track'),prev=shelf.querySelector('.shelf-prev'),next=shelf.querySelector('.shelf-next');const update=()=>{prev.disabled=track.scrollLeft<=4;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-3};const move=direction=>{const card=track.querySelector('.card');if(card)track.scrollBy({left:direction*(card.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap)),behavior:settings.motion&&!reduced.matches?'smooth':'instant'})};prev.onclick=()=>move(-1);next.onclick=()=>move(1);track.addEventListener('scroll',update,{passive:true});track.onkeydown=e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}};const observer=new ResizeObserver(update);observer.observe(track);observers.push(observer);update()});}
function animateBot(wave=false){clearTimeout(botTimer);const sprite=$('.bot-sprite');if(!sprite)return;let frame=0,row=wave?3:0;const tick=()=>{sprite.style.backgroundPosition=`${-frame*122}px ${-row*132}px`;if(!settings.bot||document.hidden)return;if(!settings.motion||reduced.matches){sprite.style.backgroundPosition='0 -396px';return;}frame++;if(frame>=(row===3?4:6)){frame=0;row=0}botTimer=setTimeout(tick,row===3?180:300)};tick();}
function applySettings(){document.body.classList.toggle('shop-no-motion',!settings.motion);document.querySelectorAll('.brand-reactor video').forEach(v=>{if(!settings.motion||reduced.matches)v.pause();else v.play().catch(()=>{})});if($('.shop-bot'))$('.shop-bot').hidden=!settings.bot;animateBot();window.dispatchEvent(new Event('shop-motion-change'));}
function privacyBanner(){if($('.shop-privacy'))return;document.body.classList.add('shop-privacy-open');document.body.insertAdjacentHTML('beforeend',`<section class="shop-privacy" aria-label="Cookies und Browser-Speicher"><div><strong>Dein Shop. Deine Datenschutzeinstellungen.</strong><p>Für Anmeldung, Warenkorb und angeforderte Downloads nutzen wir notwendige Cookies und Browser-Speicher. Es gibt keine Werbe- oder Analyse-Tracker. Optional können wir Komfortfunktionen speichern, etwa dass das Intro in dieser Sitzung schon gezeigt wurde.</p><a href="/datenschutz">Datenschutzhinweise ansehen →</a></div><div class="shop-privacy-actions"><button class="button" data-privacy-choice="necessary">Nur notwendige</button><button class="button primary" data-privacy-choice="comfort">Komfort erlauben</button><button class="button" data-open-settings>Einstellungen</button></div></section>`);document.querySelectorAll('[data-privacy-choice]').forEach(b=>b.onclick=()=>{preferences={comfort:b.dataset.privacyChoice==='comfort',version:1};store('nm-shop-privacy',preferences);if(preferences.comfort){try{sessionStorage.setItem('nm-shop-intro-shown','1')}catch{}}else{try{sessionStorage.removeItem('nm-shop-intro-shown')}catch{}}$('.shop-privacy').remove();document.body.classList.remove('shop-privacy-open');});}
function openSettings(){let dialog=$('#shopSettings');if(!dialog){dialog=document.createElement('dialog');dialog.id='shopSettings';dialog.className='shop-settings-dialog';dialog.setAttribute('aria-labelledby','shopSettingsTitle');document.body.append(dialog)}dialog.innerHTML=`<div class="settings-heading"><h2 id="shopSettingsTitle">Deine Einstellungen</h2><button class="icon-button" data-close-settings aria-label="Einstellungen schließen">×</button></div><p>Gestalte deinen Besuch im NeonMind Shop.</p><label class="settings-row"><input type="checkbox" name="intro" ${settings.intro?'checked':''}><span>Intro anzeigen<small>Kurze Begrüßung beim Besuch. Jederzeit überspringbar.</small></span></label><label class="settings-row"><input type="checkbox" name="bot" ${settings.bot?'checked':''}><span>NeonBot anzeigen<small>Shop-Hilfe und schnelle Links unten rechts.</small></span></label><label class="settings-row"><input type="checkbox" name="motion" ${settings.motion?'checked':''}><span>Animationen anzeigen<small>Logo-Ring, Farbverläufe, Figur und automatischer Slider.</small></span></label><label class="settings-row"><input type="checkbox" name="comfort" ${preferences?.comfort?'checked':''}><span>Optionale Komfortspeicherung<small>Merkt sich das bereits gezeigte Intro für diese Sitzung. Kein Tracking.</small></span></label><p>Notwendige Speicherung für Anmeldung, Warenkorb und angeforderte Funktionen bleibt verfügbar. Deine ausdrücklich gewählten Einstellungen werden auf diesem Gerät gespeichert.</p><p><a href="/datenschutz">Datenschutzhinweise →</a></p><button class="button primary" id="saveShopSettings">Einstellungen speichern</button>`;dialog.querySelector('[data-close-settings]').onclick=()=>dialog.close();$('#saveShopSettings').onclick=()=>{for(const key of ['intro','bot','motion'])settings[key]=dialog.querySelector(`[name=${key}]`).checked;preferences={comfort:dialog.querySelector('[name=comfort]').checked,version:1};store('nm-shop-settings',settings);store('nm-shop-privacy',preferences);if(!preferences.comfort){try{sessionStorage.removeItem('nm-shop-intro-shown')}catch{}}if($('.shop-privacy'))$('.shop-privacy').remove();document.body.classList.remove('shop-privacy-open');applySettings();dialog.close()};dialog.showModal();}
function intro(){if(!settings.intro||!settings.motion||reduced.matches||/^\/(admin|login|register|account|checkout|downloads|guest)/.test(location.pathname))return;try{if(preferences?.comfort&&sessionStorage.getItem('nm-shop-intro-shown'))return;if(preferences?.comfort)sessionStorage.setItem('nm-shop-intro-shown','1')}catch{}document.body.insertAdjacentHTML('beforeend',`<div class="shop-intro" role="dialog" aria-label="NeonMind Shop Begrüßung"><span class="brand-reactor"><video muted autoplay playsinline loop poster="/assets/brand-logo.png"><source src="/assets/brand-ring.mp4" type="video/mp4"></video></span><strong class="neon-flow">NEONMIND SHOP</strong><p>Deine Ideen. Deine Designwelt.</p><button type="button">Intro überspringen →</button></div>`);const overlay=$('.shop-intro'),finish=()=>overlay.remove();overlay.querySelector('button').onclick=finish;setTimeout(finish,1600);}
export function setupIdentity(){
 const menu=$('#shopMenu');if(menu)menu.querySelector('hr').insertAdjacentHTML('beforebegin','<button data-open-settings>⚙ Einstellungen</button>');
 document.addEventListener('click',e=>{if(e.target.closest('[data-open-settings]')){if(menu)menu.hidden=true;openSettings()}});
 $('#scrollTop')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:settings.motion&&!reduced.matches?'smooth':'instant'}));
 document.body.insertAdjacentHTML('beforeend',`<aside class="shop-bot" aria-label="NeonBot Shop-Hilfe"><div class="bot-bubble" hidden><button class="bot-close" aria-label="Begrüßung schließen">×</button><strong>Moin! 👋</strong><p>Willkommen im NeonMind Shop. Finde deine Designwelt – oder erzähl uns, was du dir wünschst.</p><div class="bot-links"><a href="/collections">Produkte</a><a href="/wuensche">Deine Wünsche</a><a href="/kontakt">Kontakt</a></div></div><button class="bot-character" aria-label="NeonBot Shop-Hilfe öffnen" aria-expanded="false"><span class="bot-sprite" aria-hidden="true"></span></button></aside>`);
 const toggle=show=>{$('.bot-bubble').hidden=!show;$('.bot-character').setAttribute('aria-expanded',String(show));if(show)animateBot(true)};$('.bot-character').onclick=()=>toggle($('.bot-bubble').hidden);$('.bot-close').onclick=()=>toggle(false);
 applySettings();reduced.addEventListener('change',applySettings);document.addEventListener('visibilitychange',applySettings);if(!preferences)privacyBanner();intro();setTimeout(()=>{if(settings.bot&&!document.body.classList.contains('shop-privacy-open')){toggle(true);setTimeout(()=>toggle(false),6500)}},2400);
}
